using MediatR;using JTradeERP.Application.Common.Persistence;using JTradeERP.Application.Common.Exceptions;using JTradeERP.Domain.MasterData;
namespace JTradeERP.Application.Features.MasterData.Suppliers.CreateSupplier;
public sealed class CreateSupplierHandler(IApplicationDbContext db):IRequestHandler<CreateSupplierCommand,CreateSupplierResponse>{public async Task<CreateSupplierResponse> Handle(CreateSupplierCommand r,CancellationToken ct){if(db.Suppliers.Any(x=>x.SupplierCode==r.SupplierCode.Trim()))throw new ConflictException("Supplier code already exists.");var e=new Supplier(r.SupplierCode,r.Name,r.Address,r.ContactInformation,r.PaymentTerms,r.TRN);db.Add(e);await db.SaveChangesAsync(ct);return Map(e);}internal static CreateSupplierResponse Map(Supplier e)=>new(e.Id,e.SupplierCode,e.Name,e.Address,e.ContactInformation,e.PaymentTerms,e.TRN);}
